export const legacyStyles = "\n  :root {\n    --bg: #0f1117; --bg2: #1a1d27; --bg3: #22263a;\n    --border: #2e3348; --border2: #3d4260;\n    --text: #e8eaf6; --text2: #9095b0; --text3: #5a5f78;\n    --blue: #4f8ef7; --blue-bg: #1a2540; --blue-text: #a8c4fc;\n    --green: #3fc98a; --green-bg: #142a1e; --green-text: #85e0b5;\n    --amber: #f5a623; --amber-bg: #2a1e0a; --amber-text: #fcd08a;\n    --red: #f06060; --red-bg: #2a1010; --red-text: #f7a8a8;\n    --purple: #a07cf7; --purple-bg: #1e1530; --purple-text: #c9b3fc;\n    --teal: #2dd4bf; --teal-bg: #0d2722; --teal-text: #7eeee3;\n    --coral: #f48060; --coral-bg: #2a1510; --coral-text: #f7b8a0;\n    --mono: 'Fira Code', 'Cascadia Code', monospace;\n    --sans: 'Inter', system-ui, sans-serif;\n    --radius: 8px; --radius-lg: 12px;\n  }\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  body { background: var(--bg); color: var(--text); font-family: var(--sans); font-size: 14px; line-height: 1.6; min-height: 100vh; }\n\n  /* TOP NAV */\n  .topbar { background: var(--bg2); border-bottom: 1px solid var(--border); padding: 14px 24px; display: flex; align-items: center; gap: 16px; position: sticky; top: 0; z-index: 100; }\n  .topbar h1 { font-size: 15px; font-weight: 600; color: var(--text); letter-spacing: 0.02em; }\n  .topbar .badge { font-size: 11px; background: var(--blue-bg); color: var(--blue-text); padding: 2px 8px; border-radius: 20px; border: 1px solid var(--blue); }\n  .search-wrap { margin-left: auto; position: relative; }\n  .search-wrap input { background: var(--bg3); border: 1px solid var(--border2); color: var(--text); padding: 7px 12px 7px 32px; border-radius: var(--radius); font-size: 13px; width: 220px; outline: none; }\n  .search-wrap input:focus { border-color: var(--blue); }\n  .search-wrap::before { content: '⌕'; position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: var(--text3); font-size: 15px; }\n\n  /* LAYOUT */\n  .layout { display: flex; height: calc(100vh - 53px); }\n  .sidebar { width: 210px; flex-shrink: 0; background: var(--bg2); border-right: 1px solid var(--border); overflow-y: auto; padding: 12px 0; }\n  .main { flex: 1; overflow-y: auto; padding: 24px 32px; }\n\n  /* SIDEBAR NAV */\n  .sidebar-section { font-size: 10px; font-weight: 600; color: var(--text3); text-transform: uppercase; letter-spacing: 0.1em; padding: 8px 16px 4px; }\n  .nav-item { display: flex; align-items: center; gap: 8px; padding: 7px 16px; cursor: pointer; font-size: 13px; color: var(--text2); transition: all 0.15s; border-left: 2px solid transparent; }\n  .nav-item:hover { background: var(--bg3); color: var(--text); }\n  .nav-item.active { background: var(--bg3); color: var(--blue); border-left-color: var(--blue); }\n  .nav-dot { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; }\n\n  /* SECTION PAGES */\n  .page { display: none; }\n  .page.active { display: block; }\n\n  /* PAGE HEADER */\n  .page-header { display: flex; align-items: flex-start; gap: 16px; margin-bottom: 24px; }\n  .page-icon { width: 40px; height: 40px; border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 18px; flex-shrink: 0; }\n  .page-title { font-size: 22px; font-weight: 600; color: var(--text); }\n  .page-subtitle { font-size: 13px; color: var(--text2); margin-top: 2px; }\n\n  /* CARDS GRID */\n  .cards-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 20px; }\n  .cards-grid.three { grid-template-columns: 1fr 1fr 1fr; }\n  .cards-grid.one { grid-template-columns: 1fr; }\n  @media (max-width: 900px) { .cards-grid, .cards-grid.three { grid-template-columns: 1fr; } }\n\n  /* CARD */\n  .card { background: var(--bg2); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 16px; }\n  .card-header { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; }\n  .card-title { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; }\n  .card-icon { font-size: 13px; }\n\n  /* SIGNAL TAGS */\n  .tag-list { display: flex; flex-wrap: wrap; gap: 6px; }\n  .tag { font-size: 11px; font-family: var(--mono); padding: 3px 8px; border-radius: 4px; border: 1px solid; }\n  .tag.blue { background: var(--blue-bg); color: var(--blue-text); border-color: var(--blue); }\n  .tag.green { background: var(--green-bg); color: var(--green-text); border-color: var(--green); }\n  .tag.amber { background: var(--amber-bg); color: var(--amber-text); border-color: var(--amber); }\n  .tag.red { background: var(--red-bg); color: var(--red-text); border-color: var(--red); }\n  .tag.purple { background: var(--purple-bg); color: var(--purple-text); border-color: var(--purple); }\n  .tag.teal { background: var(--teal-bg); color: var(--teal-text); border-color: var(--teal); }\n  .tag.gray { background: var(--bg3); color: var(--text2); border-color: var(--border2); }\n\n  /* BULLET LIST */\n  .bullet-list { list-style: none; }\n  .bullet-list li { padding: 4px 0 4px 16px; position: relative; font-size: 13px; color: var(--text2); }\n  .bullet-list li::before { content: ''; position: absolute; left: 4px; top: 12px; width: 4px; height: 4px; border-radius: 50%; background: var(--text3); }\n  .bullet-list.green li::before { background: var(--green); }\n  .bullet-list.red li::before { background: var(--red); }\n\n  /* USE / NOT USE */\n  .use-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n  .use-box { padding: 12px; border-radius: var(--radius); }\n  .use-box.yes { background: var(--green-bg); border: 1px solid #1e4a30; }\n  .use-box.no { background: var(--red-bg); border: 1px solid #4a1e1e; }\n  .use-label { font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 8px; }\n  .use-box.yes .use-label { color: var(--green); }\n  .use-box.no .use-label { color: var(--red); }\n  .use-box ul { list-style: none; }\n  .use-box li { font-size: 12px; padding: 2px 0; }\n  .use-box.yes li { color: var(--green-text); }\n  .use-box.no li { color: var(--red-text); }\n\n  /* PROBLEMS TABLE */\n  .prob-table { width: 100%; border-collapse: collapse; }\n  .prob-table th { font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text3); padding: 6px 10px; text-align: left; border-bottom: 1px solid var(--border); }\n  .prob-table td { padding: 7px 10px; font-size: 13px; border-bottom: 1px solid var(--border); }\n  .prob-table tr:last-child td { border-bottom: none; }\n  .diff { font-size: 11px; font-weight: 600; padding: 2px 7px; border-radius: 4px; }\n  .diff.E { background: var(--green-bg); color: var(--green-text); }\n  .diff.M { background: var(--amber-bg); color: var(--amber-text); }\n  .diff.H { background: var(--red-bg); color: var(--red-text); }\n  .prob-name { color: var(--text); }\n  .prob-note { font-size: 11px; color: var(--text3); }\n\n  /* DIVIDER */\n  .divider { height: 1px; background: var(--border); margin: 20px 0; }\n\n  /* COMPARISON SECTION */\n  .vs-card { background: var(--bg2); border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: hidden; margin-bottom: 14px; }\n  .vs-header { padding: 12px 16px; background: var(--bg3); border-bottom: 1px solid var(--border); display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 600; color: var(--text); }\n  .vs-body { display: grid; grid-template-columns: 1fr 1fr; }\n  .vs-col { padding: 14px 16px; }\n  .vs-col:first-child { border-right: 1px solid var(--border); }\n  .vs-col-title { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 10px; }\n  .vs-col ul { list-style: none; }\n  .vs-col li { font-size: 12px; color: var(--text2); padding: 3px 0; padding-left: 12px; position: relative; }\n  .vs-col li::before { content: '→'; position: absolute; left: 0; color: var(--text3); font-size: 11px; }\n  .vs-rule { background: var(--amber-bg); border-top: 1px solid var(--border); padding: 10px 16px; font-size: 12px; color: var(--amber-text); }\n  .vs-rule strong { color: var(--amber); }\n\n  /* DECISION TREE */\n  .decision-tree { display: flex; flex-direction: column; gap: 8px; }\n  .dt-row { display: flex; align-items: stretch; gap: 0; background: var(--bg2); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }\n  .dt-if { background: var(--bg3); padding: 10px 14px; font-size: 12px; color: var(--text2); min-width: 280px; flex-shrink: 0; border-right: 1px solid var(--border); font-family: var(--mono); }\n  .dt-if span { color: var(--blue-text); font-weight: 600; font-size: 11px; display: block; margin-bottom: 2px; text-transform: uppercase; letter-spacing: 0.05em; }\n  .dt-then { padding: 10px 14px; font-size: 12px; display: flex; align-items: center; gap: 8px; flex: 1; }\n  .dt-pattern { font-weight: 600; color: var(--text); font-family: var(--mono); font-size: 12px; }\n  .dt-why { color: var(--text3); font-size: 11px; }\n  .dt-badge { font-size: 10px; padding: 2px 7px; border-radius: 3px; font-weight: 600; flex-shrink: 0; }\n\n  /* CATEGORY HEADERS */\n  .section-title { font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.1em; color: var(--text3); margin: 24px 0 10px; display: flex; align-items: center; gap: 8px; }\n  .section-title::after { content: ''; flex: 1; height: 1px; background: var(--border); }\n\n  /* PATTERN GRID (home) */\n  .pattern-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }\n  .pattern-card { background: var(--bg2); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 14px; cursor: pointer; transition: all 0.15s; }\n  .pattern-card:hover { border-color: var(--blue); background: var(--bg3); }\n  .pattern-card .pc-title { font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 4px; }\n  .pattern-card .pc-tags { font-size: 11px; color: var(--text3); font-family: var(--mono); }\n\n  /* HOME STATS */\n  .stats-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 24px; }\n  .stat-box { background: var(--bg2); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 14px; text-align: center; }\n  .stat-num { font-size: 26px; font-weight: 600; }\n  .stat-label { font-size: 11px; color: var(--text2); margin-top: 2px; }\n\n  /* CODE */\n  code { font-family: var(--mono); font-size: 12px; background: var(--bg3); padding: 1px 5px; border-radius: 3px; color: var(--teal-text); }\n\n  /* SCROLLBAR */\n  ::-webkit-scrollbar { width: 6px; height: 6px; }\n  ::-webkit-scrollbar-track { background: transparent; }\n  ::-webkit-scrollbar-thumb { background: var(--border2); border-radius: 3px; }\n\n  /* FILTER TABS */\n  .filter-tabs { display: flex; gap: 6px; margin-bottom: 16px; flex-wrap: wrap; }\n  .ftab { font-size: 12px; padding: 4px 12px; border-radius: 20px; border: 1px solid var(--border2); cursor: pointer; color: var(--text2); background: transparent; transition: all 0.15s; }\n  .ftab:hover, .ftab.active { background: var(--blue-bg); color: var(--blue-text); border-color: var(--blue); }\n\n  /* HIGHLIGHT */\n  .highlight { background: #2a2400; color: var(--amber-text); border-radius: 2px; }\n";

